// ~/.partition/statusline.mjs 내용. settings.json에는 이 고정 경로를 등록하고,
// 실행기는 install.json의 현재 플러그인 경로를 따라간다(업데이트로 경로가 바뀌어도 동작).

export function launcherSource() {
  return `#!/usr/bin/env node
// Partition status line launcher. Generated by Partition; do not edit.
// Runs the status line of the currently installed plugin (see install.json).
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

try {
  const install = JSON.parse(readFileSync(new URL('./install.json', import.meta.url), 'utf8'));
  const mod = await import(pathToFileURL(join(install.pluginRoot, 'src/claude/statusline.mjs')).href);
  mod.main();
} catch {
  process.stdout.write('[Partition: not found — run /partition:setup]\\n');
}
`;
}
